  class DynamicMixedPrecisionQuantizer:
      def __init__(self, model, calibration_data):
          self.model = model
          self.calibration_data = calibration_data
          self.precision_map = {}
          
      def analyze_sensitivity(self):
          # Per-layer sensitivity analysis
          sensitivities = {}
          for name, module in self.model.named_modules():
              if isinstance(module, (nn.Linear, nn.Conv2d)):
                  # Measure KL divergence between FP32 and quantized output
                  sensitivities[name] = self._compute_kl_divergence(module)
          return sensitivities
          
      def allocate_precision(self, budget=0.5):
          # Allocate higher precision to sensitive layers
          sensitivities = self.analyze_sensitivity()
          sorted_layers = sorted(sensitivities.items(), key=lambda x: x[1])
          
          # Budget: fraction of layers at INT8 vs INT4
          int8_count = int(len(sorted_layers) * budget)
          for i, (name, _) in enumerate(sorted_layers):
              if i < int8_count:
                  self.precision_map[name] = torch.int8
              else:
                  self.precision_map[name] = torch.quint4x2